-- Phase 2: auditable scientific ingestion and research-agent subsystem.
create table ingestion_sources (id uuid primary key default gen_random_uuid(), provider text not null unique, provider_type text not null, base_url text, status text not null, configuration jsonb not null default '{}', last_successful_sync_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table ingestion_runs (id uuid primary key default gen_random_uuid(), ingestion_source_id uuid not null references ingestion_sources, run_type text not null check(run_type in ('manual_search','targeted_refresh','scheduled_refresh','entity_enrichment','opportunity_diligence')), query_payload jsonb not null, status text not null, started_at timestamptz not null, completed_at timestamptz, records_found integer not null default 0, records_imported integer not null default 0, records_failed integer not null default 0, error_summary text, created_by_type text not null, created_by_user_id uuid);
create table raw_ingestion_records (id uuid primary key default gen_random_uuid(), ingestion_run_id uuid not null references ingestion_runs, provider_record_id text not null, provider_url text, record_type text not null, raw_payload jsonb not null, raw_text text, content_hash text not null, retrieved_at timestamptz not null, processing_status text not null, processing_error text, unique(ingestion_run_id,provider_record_id), unique(content_hash));
create table normalized_scientific_records (id uuid primary key default gen_random_uuid(), raw_ingestion_record_id uuid not null unique references raw_ingestion_records, normalized_type text not null, title text not null, abstract_or_summary text, publication_date date, identifiers jsonb not null default '{}', authors jsonb not null default '[]', organizations jsonb not null default '[]', normalized_payload jsonb not null, normalization_version text not null, created_at timestamptz not null default now());
create table entity_aliases (id uuid primary key default gen_random_uuid(), entity_type text not null, entity_id uuid not null, alias text not null, alias_type text not null, source text not null, confidence confidence_grade not null, human_verified boolean not null default false, created_at timestamptz not null default now(), unique(entity_type,lower(alias),entity_id));
create table entity_resolution_tasks (id uuid primary key default gen_random_uuid(), entity_type text not null, raw_value text not null, candidate_matches jsonb not null default '[]', confidence confidence_grade not null, status text not null, resolved_entity_id uuid, resolved_by_user_id uuid, created_at timestamptz not null default now(), resolved_at timestamptz);
create table evidence_clusters (id uuid primary key default gen_random_uuid(), cluster_type text not null, canonical_study_identifier text, description text not null, created_at timestamptz not null default now());
create table evidence_cluster_members (evidence_cluster_id uuid references evidence_clusters on delete cascade, source_id uuid references sources on delete cascade, primary key(evidence_cluster_id,source_id));
create table research_runs (id uuid primary key default gen_random_uuid(), search_run_id uuid references search_runs, opportunity_id uuid references opportunities, family_id uuid references opportunity_families, research_type text not null, status text not null, research_plan jsonb not null, started_at timestamptz not null, completed_at timestamptz, initiated_by_type text not null, initiated_by_user_id uuid, model_configuration jsonb not null default '{}', budget_configuration jsonb not null, usage_metadata jsonb not null default '{}', summary text, check(num_nonnulls(search_run_id,opportunity_id,family_id)<=1));
create table research_tasks (id uuid primary key default gen_random_uuid(), research_run_id uuid not null references research_runs on delete cascade, parent_task_id uuid references research_tasks, agent_type text not null, objective text not null, input_payload jsonb not null, output_payload jsonb, status text not null, attempt_count integer not null default 0, started_at timestamptz, completed_at timestamptz, error text);
create table prompt_templates (id uuid primary key default gen_random_uuid(), name text not null, agent_type text not null, version text not null, system_prompt text not null, user_prompt_template text not null, output_schema_name text not null, status text not null, created_at timestamptz not null default now(), unique(name,version));
create table assessment_proposals (id uuid primary key default gen_random_uuid(), criterion_id uuid not null references scoring_criteria, target_entity_type text not null, target_entity_id uuid not null, proposed_score integer not null check(proposed_score between 0 and 5), proposed_confidence confidence_grade not null, baseline_confidence confidence_grade not null, confidence_derivation jsonb not null, rationale text not null, supporting_evidence_claim_ids uuid[] not null default '{}', contradicting_evidence_claim_ids uuid[] not null default '{}', analysis_run_id uuid references ai_analysis_runs, research_task_id uuid references research_tasks, status text not null check(status in ('pending','accepted','modified','rejected')), reviewed_by_user_id uuid, reviewed_at timestamptz, created_at timestamptz not null default now());
create table constraint_proposals (id uuid primary key default gen_random_uuid(), mechanism_context_id uuid not null references mechanism_contexts, constraint_type_id uuid not null references constraint_types, statement text not null, clinical_manifestation text not null, causal_hypothesis text not null, supporting_observation_ids uuid[] not null default '{}', proposed_severity integer check(proposed_severity between 0 and 5), proposed_causality integer check(proposed_causality between 0 and 5), confidence confidence_grade not null, alternative_explanations jsonb not null default '[]', research_task_id uuid references research_tasks, status text not null, reviewed_by_user_id uuid, reviewed_at timestamptz, created_at timestamptz not null default now());
create table transformation_hypothesis_proposals (id uuid primary key default gen_random_uuid(), constraint_id uuid references constraints, transformation_id uuid not null references transformations, drug_property_id uuid not null references drug_properties, clinical_advantage_id uuid not null references clinical_advantages, rationale text not null, prerequisites jsonb not null, supporting_evidence_claim_ids uuid[] not null default '{}', proposed_transformation_fit integer check(proposed_transformation_fit between 0 and 5), proposed_technical_feasibility integer check(proposed_technical_feasibility between 0 and 5), confidence confidence_grade not null, research_task_id uuid references research_tasks, status text not null, reviewed_by_user_id uuid, reviewed_at timestamptz, created_at timestamptz not null default now());
create table review_queue_items (id uuid primary key default gen_random_uuid(), category text not null, entity_type text not null, entity_id uuid not null, priority text not null, title text not null, summary text not null, status text not null check(status in ('pending','accepted','modified','rejected','deferred')), reviewer_rationale text, reviewed_by_user_id uuid, reviewed_at timestamptz, created_at timestamptz not null default now());
create table refresh_policies (id uuid primary key default gen_random_uuid(), entity_type text not null unique, max_age_days integer not null, rationale text not null, active boolean not null default true);
create table research_snapshots (id uuid primary key default gen_random_uuid(), entity_type text not null, entity_id uuid not null, evidence_claim_ids uuid[] not null, assessment_ids uuid[] not null, snapshot_payload jsonb not null, created_at timestamptz not null default now());
create table decision_change_alerts (id uuid primary key default gen_random_uuid(), entity_type text not null, entity_id uuid not null, alert_type text not null, previous_state jsonb not null, proposed_state jsonb not null, severity text not null, status text not null default 'open', created_at timestamptz not null default now(), acknowledged_at timestamptz);
create index raw_ingestion_provider_idx on raw_ingestion_records(provider_record_id,content_hash,processing_status);
create index resolution_queue_idx on entity_resolution_tasks(status,confidence,entity_type);
create index research_run_idx on research_runs(status,research_type,started_at);
create index research_task_idx on research_tasks(research_run_id,status,agent_type);
create index review_queue_idx on review_queue_items(status,category,priority,created_at);
insert into refresh_policies(entity_type,max_age_days,rationale) values ('clinical_pipeline_status',30,'Development status changes frequently'),('approved_mechanism_validation',365,'Established approvals are comparatively stable'),('patent_status',90,'Refresh before high-stakes defensibility decisions'),('competitive_landscape',45,'Active programs and transactions change frequently');
